-- 1. Custom Domain with Regex Check Constraint
CREATE DOMAIN valid_email AS TEXT
CHECK (VALUE ~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2}$');

-- 2. Custom Composite Type for Addresses
CREATE TYPE address_type AS (
    street VARCHAR(100),
    city VARCHAR(50),
    postal_code VARCHAR(20)
);

CREATE TABLE clients (
    id SERIAL PRIMARY KEY,
    email valid_email NOT NULL,
    shipping_address address_type
);

CREATE DOMAIN email_address AS TEXT
    CONSTRAINT email_not_blank CHECK (VALUE = btrim(VALUE) AND position('@' IN VALUE) > 1);

CREATE DOMAIN positive_money AS NUMERIC(12,2)
    DEFAULT 0
    CONSTRAINT must_be_positive CHECK (VALUE >= 0);

CREATE DOMAIN iso_country AS TEXT
    CONSTRAINT two_letters CHECK (VALUE ~ '^[A-Z]{2}$');

CREATE TABLE customers (
    id      BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email   email_address NOT NULL,
    country iso_country   NOT NULL,
    balance positive_money NOT NULL
);

INSERT INTO customers (email, country, balance) VALUES ('ada@example.com', 'gb', 10);
-- ERROR: value for domain iso_country violates check constraint "two_letters"

-- Altering a domain re-validates every dependent column
ALTER DOMAIN positive_money ADD CONSTRAINT not_absurd CHECK (VALUE < 1e12);

CREATE TYPE address AS (
    line1       TEXT,
    city        TEXT,
    postal_code TEXT,
    country     iso_country
);

CREATE TABLE clients (
    id       BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name     TEXT NOT NULL,
    shipping address
);

INSERT INTO clients (name, shipping)
VALUES ('Acme Ltd', ROW('1 Main St','Springfield','12345','US')::address);

-- Access a field: parentheses are required
SELECT name,
       (shipping).city          AS city,
       (shipping).country       AS country
FROM clients
WHERE (shipping).country = 'US';

-- Update a single field
UPDATE clients SET shipping.city = 'Shelbyville' WHERE name = 'Acme Ltd';

-- A function returning a composite value
CREATE FUNCTION primary_address(c clients) RETURNS address AS $$
    SELECT c.shipping;
$$ LANGUAGE sql STABLE;
